function getMaxRoadClass(x,y,r=1){
  let mx=0;
  for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){
    const nx=x+dx,ny=y+dy;
    if(!inMap(nx,ny))continue;
    const t=T(idx(nx,ny));
    if(t.road&&t.rc>mx)mx=t.rc;
  }
  return mx;
}

